import { render } from '@solidjs/web';
import { createSignal, createMemo } from 'solid-js';

const adjectives = ['Blue', 'Tiny', 'Smart', 'Classic', 'Rustic', 'Glass', 'Paper', 'Steel'];
const things = ['mug', 'lamp', 'chair', 'notebook', 'bottle', 'clock', 'pen', 'bag'];
const products = Array.from({ length: 2000 }, (_, i) => ({
  id: i,
  name: `${adjectives[i % 8]} ${things[Math.floor(i / 8) % 8]} ${i}`,
}));

let runs = 0;

function Search() {
  const [query, setQuery] = createSignal('');
  const filtered = () => {
    console.log('filter run', ++runs);
    return products.filter((product) => product.name.includes(query()));
  };

  return (
    <>
      <input
        placeholder="Search products"
        onInput={(event) => setQuery(event.currentTarget.value)}
      />
      <p>{filtered().length} matches</p>
      <p>First match: {filtered()[0]?.name ?? 'none'}</p>
      <p>{filtered().length === 0 ? 'Try a shorter search.' : ''}</p>
    </>
  );
}

render(() => <Search />, document.getElementById('app'));

